  "revision_action": "keep",
  "supportive_card_ids": ["C07", "C11", "C17", "C18", "C03", "C19", "C02", "C52", "C47"],
  "contradictory_card_ids": ["C46", "C48", "C54", "C43", "C45", "C51"],
  "prediction_basis_card_ids": ["C07", "C11", "C17", "C52"],
  "claims": [
    {
      "claim": "The closest measured oral-bioavailability context, cladribine (2-chloro-2'-deoxyadenosine), shows absolute F of 36–46% in fasted patients, clearly above the 20% threshold.",
      "card_ids": ["C07", "C11", "C17"]
    },
    {
      "claim": "Other nucleoside analog contexts (zalcitabine, lamivudine, emtricitabine, didanosine) all exceed 20%, supporting a class-level expectation for meaningful oral absorption of small nucleoside analogs.",
      "card_ids": ["C18", "C29", "C03", "C06", "C16", "C20", "C25", "C26", "C19", "C30", "C02", "C09"]
    },
    {
      "claim": "L4 provides high gastric solubility for the closely related 2-fluoroadenosine (M02) and measurable intestinal flux for 3TC, supporting absorption potential for the query's nucleoside scaffold.",
      "card_ids": ["C52", "C47"]
    },
    {
      "claim": "L4 low Caco-2 permeability records for other polar nucleosides/nucleotides (levovirin, gemcitabine, PMPA, PMEA) raise absorption uncertainty but are not direct F measurements for the query and do not affirmatively establish F < 20%.",
      "card_ids": ["C46", "C48", "C54", "C43", "C45", "C51"]
    },
    {
      "claim": "No affirmative threshold-relevant evidence supports F < 20% for the query; low paliperidone outcomes arise from a different structural class and modified-release formulation context and are not transferable.",
      "card_ids": ["C01", "C21", "C27", "C28"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C52", "C47", "C46", "C48", "C54", "C43", "C45", "C51"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the exact query molecule.",
    "The query's pyranose sugar differs from cladribine's deoxyribose and from 2-fluoroadenosine's ribofuranose; transporter affinity and absorption are unmeasured.",
    "No fed/fasted condition, dose, formulation, or species information is available for the query.",
    "No first-pass metabolism or clearance data are available for the query.",
    "L4 permeability records are for other molecules, not the query, and are not direct systemic-F outcomes."
  ],
  "decision_summary": "The query is a polar 2-fluoroadenine pyranose nucleoside. Direct F measurements for the closest structural context cladribine (36–46%) and other nucleoside analogs all exceed 20%. L4 adds high solubility for 2-fluoroadenosine and intestinal flux for 3TC, while low Caco-2 permeability records for other nucleosides/nucleotides are not direct F evidence for the query and do not affirmatively support F < 20%. Therefore the prediction remains high with moderate confidence."
}

